-- SPNB DIGITAL core schema
-- Target: Supabase PostgreSQL
-- Raw QR/NFC tokens and reset secrets must be generated by a trusted server and never stored.

create extension if not exists pgcrypto with schema extensions;

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated, service_role;

create or replace function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create table public.accounts (
  user_id uuid primary key references auth.users(id) on delete cascade,
  phone_e164 text not null unique check (phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  display_name text,
  status text not null default 'active' check (status in ('active', 'suspended')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.account_roles (
  user_id uuid not null references public.accounts(user_id) on delete cascade,
  role text not null check (role in ('admin', 'reseller', 'owner')),
  created_at timestamptz not null default now(),
  primary key (user_id, role)
);

create table public.resellers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone_e164 text check (phone_e164 is null or phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  city text,
  status text not null default 'active' check (status in ('active', 'suspended', 'closed')),
  created_by uuid not null references public.accounts(user_id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.reseller_members (
  reseller_id uuid not null references public.resellers(id) on delete cascade,
  user_id uuid not null references public.accounts(user_id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (reseller_id, user_id)
);

create table public.businesses (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.accounts(user_id),
  status text not null default 'active' check (status in ('active', 'hidden', 'suspended')),
  name text not null check (char_length(name) between 2 and 120),
  description text check (description is null or char_length(description) <= 500),
  logo_url text,
  cover_url text,
  google_review_url text check (
    google_review_url is null
    or google_review_url ~* '^https://([^/?#]+\.)?(google\.[a-z.]+|g\.page|maps\.app\.goo\.gl)([/?#]|$)'
  ),
  google_maps_url text check (
    google_maps_url is null
    or google_maps_url ~* '^https://([^/?#]+\.)?(google\.[a-z.]+|g\.page|maps\.app\.goo\.gl)([/?#]|$)'
  ),
  whatsapp_e164 text check (whatsapp_e164 is null or whatsapp_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  address text,
  business_hours text,
  theme_color text not null default '#1769c2' check (theme_color ~ '^#[0-9A-Fa-f]{6}$'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, owner_id)
);

create table public.business_slugs (
  slug text primary key check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and char_length(slug) between 3 and 80),
  business_id uuid not null references public.businesses(id) on delete cascade,
  is_current boolean not null default true,
  created_at timestamptz not null default now(),
  retired_at timestamptz
);

create unique index business_slugs_one_current_per_business
  on public.business_slugs (business_id)
  where is_current;

create table public.profile_links (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  link_type text not null check (link_type in ('google_review', 'whatsapp', 'google_maps', 'instagram', 'tiktok', 'facebook', 'website', 'custom')),
  label text not null check (char_length(label) between 1 and 60),
  destination_url text not null check (destination_url ~ '^https://'),
  sort_order smallint not null default 0 check (sort_order >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.card_batches (
  id uuid primary key default gen_random_uuid(),
  batch_code text not null unique,
  serial_prefix text not null default 'KRT' check (serial_prefix ~ '^[A-Z0-9-]{2,12}$'),
  starting_number integer not null check (starting_number > 0),
  quantity integer not null check (quantity between 1 and 5000),
  status text not null default 'draft' check (status in ('draft', 'generated', 'in_production', 'ready', 'closed')),
  created_by uuid not null references public.accounts(user_id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.cards (
  id uuid primary key default gen_random_uuid(),
  serial text not null unique,
  batch_id uuid references public.card_batches(id),
  lifecycle_state text not null default 'admin_stock' check (lifecycle_state in ('admin_stock', 'reseller_stock', 'sold_unclaimed', 'claimed', 'retired')),
  service_state text not null default 'enabled' check (service_state in ('enabled', 'suspended')),
  provisioning_state text not null default 'draft' check (provisioning_state in ('draft', 'ready')),
  assigned_reseller_id uuid references public.resellers(id),
  owner_id uuid references public.accounts(user_id),
  business_id uuid,
  destination_mode text not null default 'direct_google' check (destination_mode in ('direct_google', 'profile')),
  qr_printed_at timestamptz,
  nfc_written_at timestamptz,
  provisioned_at timestamptz,
  claimed_at timestamptz,
  retired_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (business_id, owner_id) references public.businesses(id, owner_id),
  check (business_id is null or owner_id is not null),
  check (
    lifecycle_state = 'retired'
    or (lifecycle_state = 'admin_stock' and assigned_reseller_id is null and owner_id is null)
    or (lifecycle_state in ('reseller_stock', 'sold_unclaimed') and assigned_reseller_id is not null and owner_id is null)
    or (lifecycle_state = 'claimed' and owner_id is not null and business_id is not null)
  )
);

create table public.card_tokens (
  id uuid primary key default gen_random_uuid(),
  card_id uuid not null references public.cards(id) on delete cascade,
  kind text not null check (kind in ('qr', 'nfc')),
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  rotated_by uuid references public.accounts(user_id)
);

create unique index card_tokens_one_active_kind
  on public.card_tokens (card_id, kind)
  where revoked_at is null;

create table public.stock_transfers (
  id uuid primary key default gen_random_uuid(),
  reseller_id uuid not null references public.resellers(id),
  created_by uuid not null references public.accounts(user_id),
  idempotency_key uuid not null,
  note text,
  created_at timestamptz not null default now(),
  unique (created_by, idempotency_key)
);

create table public.stock_transfer_items (
  transfer_id uuid not null references public.stock_transfers(id) on delete restrict,
  card_id uuid not null references public.cards(id) on delete restrict,
  created_at timestamptz not null default now(),
  primary key (transfer_id, card_id)
);

create table public.card_sales (
  id uuid primary key default gen_random_uuid(),
  card_id uuid not null references public.cards(id) on delete restrict,
  reseller_id uuid not null references public.resellers(id),
  marked_by uuid not null references public.accounts(user_id),
  idempotency_key uuid not null,
  sold_at timestamptz not null default now(),
  reversed_at timestamptz,
  reversed_by uuid references public.accounts(user_id),
  reverse_reason text,
  unique (marked_by, idempotency_key)
);

create unique index card_sales_one_open_sale
  on public.card_sales (card_id)
  where reversed_at is null;

create table public.card_claims (
  id uuid primary key default gen_random_uuid(),
  card_id uuid not null references public.cards(id) on delete restrict,
  owner_id uuid not null references public.accounts(user_id),
  business_id uuid not null references public.businesses(id),
  claimed_at timestamptz not null default now(),
  released_at timestamptz,
  released_by uuid references public.accounts(user_id),
  release_reason text
);

create unique index card_claims_one_current_owner
  on public.card_claims (card_id)
  where released_at is null;

create table private.claim_sessions (
  id uuid primary key default gen_random_uuid(),
  card_id uuid not null references public.cards(id) on delete cascade,
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create table private.password_reset_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.accounts(user_id) on delete cascade,
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  requested_by uuid not null references public.accounts(user_id),
  expires_at timestamptz not null,
  used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

create table public.interaction_events (
  id bigint generated always as identity primary key,
  occurred_at timestamptz not null default now(),
  event_type text not null check (event_type in ('qr_scan', 'nfc_tap', 'profile_view', 'profile_link_click')),
  card_id uuid references public.cards(id) on delete set null,
  business_id uuid references public.businesses(id) on delete set null,
  profile_link_id uuid references public.profile_links(id) on delete set null,
  token_kind text check (token_kind is null or token_kind in ('qr', 'nfc')),
  destination_mode text check (destination_mode is null or destination_mode in ('direct_google', 'profile')),
  anonymous_session_hash text,
  request_id uuid,
  user_agent_class text,
  ip_hash text,
  is_likely_bot boolean not null default false,
  metadata jsonb not null default '{}'::jsonb
);

create table public.audit_log (
  id bigint generated always as identity primary key,
  occurred_at timestamptz not null default now(),
  actor_user_id uuid references public.accounts(user_id),
  actor_role text,
  action text not null,
  entity_type text not null,
  entity_id text not null,
  request_id uuid,
  old_values jsonb,
  new_values jsonb,
  metadata jsonb not null default '{}'::jsonb
);

create index cards_reseller_state_idx on public.cards (assigned_reseller_id, lifecycle_state);
create index cards_owner_idx on public.cards (owner_id);
create index cards_business_idx on public.cards (business_id);
create index events_card_time_idx on public.interaction_events (card_id, occurred_at desc);
create index events_business_time_idx on public.interaction_events (business_id, occurred_at desc);
create index events_link_time_idx on public.interaction_events (profile_link_id, occurred_at desc);
create index audit_entity_time_idx on public.audit_log (entity_type, entity_id, occurred_at desc);
create index claim_sessions_expiry_idx on private.claim_sessions (expires_at) where consumed_at is null;
create index password_resets_expiry_idx on private.password_reset_requests (expires_at) where used_at is null and revoked_at is null;

create trigger accounts_updated_at before update on public.accounts
for each row execute function private.set_updated_at();
create trigger resellers_updated_at before update on public.resellers
for each row execute function private.set_updated_at();
create trigger businesses_updated_at before update on public.businesses
for each row execute function private.set_updated_at();
create trigger profile_links_updated_at before update on public.profile_links
for each row execute function private.set_updated_at();
create trigger batches_updated_at before update on public.card_batches
for each row execute function private.set_updated_at();
create trigger cards_updated_at before update on public.cards
for each row execute function private.set_updated_at();

create or replace function private.validate_card_provisioning()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  active_kinds integer;
begin
  if new.provisioning_state = 'ready' and old.provisioning_state <> 'ready' then
    select count(distinct ct.kind) into active_kinds
    from public.card_tokens ct
    where ct.card_id = new.id and ct.revoked_at is null;

    if active_kinds <> 2 then
      raise exception 'A ready card requires one active QR token and one active NFC token';
    end if;
    new.provisioned_at = coalesce(new.provisioned_at, now());
  end if;
  return new;
end;
$$;

create trigger validate_card_provisioning_before_update
before update of provisioning_state on public.cards
for each row execute function private.validate_card_provisioning();

-- New self-service sign-ups become owners. Admin/reseller accounts must be provisioned by trusted server code.
create or replace function private.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  normalized_phone text;
begin
  normalized_phone := coalesce(new.phone, new.raw_user_meta_data ->> 'phone_e164');
  if normalized_phone is null or normalized_phone !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'A normalized phone number is required';
  end if;

  insert into public.accounts (user_id, phone_e164, display_name)
  values (new.id, normalized_phone, nullif(new.raw_user_meta_data ->> 'display_name', ''));

  insert into public.account_roles (user_id, role)
  values (new.id, 'owner');

  return new;
end;
$$;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function private.handle_new_auth_user();

create or replace function private.has_role(required_role text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.account_roles ar
    join public.accounts a on a.user_id = ar.user_id
    where ar.user_id = auth.uid()
      and ar.role = required_role
      and a.status = 'active'
  );
$$;

create or replace function private.is_reseller_member(target_reseller uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.reseller_members rm
    join public.resellers r on r.id = rm.reseller_id
    join public.accounts a on a.user_id = rm.user_id
    where rm.user_id = auth.uid()
      and rm.reseller_id = target_reseller
      and r.status = 'active'
      and a.status = 'active'
  );
$$;

grant execute on function private.has_role(text) to authenticated;
grant execute on function private.is_reseller_member(uuid) to authenticated;

-- A reseller-safe inventory API. It deliberately does not return owner or business identifiers.
create or replace function public.get_my_reseller_inventory()
returns table (
  card_id uuid,
  serial text,
  lifecycle_state text,
  service_state text,
  provisioning_state text,
  allocated_at timestamptz,
  sold_at timestamptz,
  claimed_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    c.id,
    c.serial,
    c.lifecycle_state,
    c.service_state,
    c.provisioning_state,
    (
      select max(st.created_at)
      from public.stock_transfer_items sti
      join public.stock_transfers st on st.id = sti.transfer_id
      where sti.card_id = c.id and st.reseller_id = c.assigned_reseller_id
    ),
    (
      select max(cs.sold_at)
      from public.card_sales cs
      where cs.card_id = c.id and cs.reversed_at is null
    ),
    c.claimed_at
  from public.cards c
  where c.assigned_reseller_id in (
    select rm.reseller_id
    from public.reseller_members rm
    where rm.user_id = auth.uid()
  )
  order by c.created_at desc;
$$;

revoke all on function public.get_my_reseller_inventory() from public;
grant execute on function public.get_my_reseller_inventory() to authenticated;

create or replace function public.allocate_cards_to_reseller(
  p_card_ids uuid[],
  p_reseller_id uuid,
  p_idempotency_key uuid,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_transfer_id uuid;
  v_locked_ids uuid[];
  v_requested_count integer;
begin
  if not private.has_role('admin') then
    raise exception 'Forbidden';
  end if;

  select st.id into v_transfer_id
  from public.stock_transfers st
  where st.created_by = auth.uid() and st.idempotency_key = p_idempotency_key;
  if v_transfer_id is not null then
    return v_transfer_id;
  end if;

  v_requested_count := coalesce(cardinality(p_card_ids), 0);
  if v_requested_count = 0 then
    raise exception 'At least one card is required';
  end if;

  if not exists (select 1 from public.resellers r where r.id = p_reseller_id and r.status = 'active') then
    raise exception 'Reseller is not active';
  end if;

  select array_agg(locked.id) into v_locked_ids
  from (
    select c.id
    from public.cards c
    where c.id = any(p_card_ids)
      and c.lifecycle_state = 'admin_stock'
      and c.service_state = 'enabled'
      and c.provisioning_state = 'ready'
    for update
  ) locked;

  if coalesce(cardinality(v_locked_ids), 0) <> v_requested_count then
    raise exception 'One or more cards are unavailable';
  end if;

  insert into public.stock_transfers (reseller_id, created_by, idempotency_key, note)
  values (p_reseller_id, auth.uid(), p_idempotency_key, p_note)
  returning id into v_transfer_id;

  insert into public.stock_transfer_items (transfer_id, card_id)
  select v_transfer_id, unnest(v_locked_ids);

  update public.cards
  set lifecycle_state = 'reseller_stock', assigned_reseller_id = p_reseller_id
  where id = any(v_locked_ids);

  insert into public.audit_log (actor_user_id, actor_role, action, entity_type, entity_id, request_id, new_values)
  values (auth.uid(), 'admin', 'cards_allocated', 'stock_transfer', v_transfer_id::text, p_idempotency_key,
          jsonb_build_object('reseller_id', p_reseller_id, 'card_count', v_requested_count));

  return v_transfer_id;
end;
$$;

revoke all on function public.allocate_cards_to_reseller(uuid[], uuid, uuid, text) from public;
grant execute on function public.allocate_cards_to_reseller(uuid[], uuid, uuid, text) to authenticated;

create or replace function public.mark_card_sold(
  p_card_id uuid,
  p_idempotency_key uuid
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_card public.cards%rowtype;
  v_sale_id uuid;
begin
  select cs.id into v_sale_id
  from public.card_sales cs
  where cs.marked_by = auth.uid() and cs.idempotency_key = p_idempotency_key;
  if v_sale_id is not null then
    return v_sale_id;
  end if;

  select * into v_card from public.cards where id = p_card_id for update;
  if not found or v_card.lifecycle_state <> 'reseller_stock' then
    raise exception 'Card is not available for sale';
  end if;
  if not private.is_reseller_member(v_card.assigned_reseller_id) then
    raise exception 'Forbidden';
  end if;

  update public.cards set lifecycle_state = 'sold_unclaimed' where id = p_card_id;
  insert into public.card_sales (card_id, reseller_id, marked_by, idempotency_key)
  values (p_card_id, v_card.assigned_reseller_id, auth.uid(), p_idempotency_key)
  returning id into v_sale_id;

  insert into public.audit_log (actor_user_id, actor_role, action, entity_type, entity_id, request_id)
  values (auth.uid(), 'reseller', 'card_marked_sold', 'card', p_card_id::text, p_idempotency_key);
  return v_sale_id;
end;
$$;

revoke all on function public.mark_card_sold(uuid, uuid) from public;
grant execute on function public.mark_card_sold(uuid, uuid) to authenticated;

create or replace function public.reverse_unclaimed_sale(p_card_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_card public.cards%rowtype;
begin
  select * into v_card from public.cards where id = p_card_id for update;
  if not found or v_card.lifecycle_state <> 'sold_unclaimed' or v_card.owner_id is not null then
    raise exception 'Only an unclaimed sale can be reversed';
  end if;
  if not (private.has_role('admin') or private.is_reseller_member(v_card.assigned_reseller_id)) then
    raise exception 'Forbidden';
  end if;

  update public.card_sales
  set reversed_at = now(), reversed_by = auth.uid(), reverse_reason = p_reason
  where card_id = p_card_id and reversed_at is null;
  update public.cards set lifecycle_state = 'reseller_stock' where id = p_card_id;

  insert into public.audit_log (actor_user_id, actor_role, action, entity_type, entity_id, new_values)
  values (auth.uid(), case when private.has_role('admin') then 'admin' else 'reseller' end,
          'card_sale_reversed', 'card', p_card_id::text, jsonb_build_object('reason', p_reason));
end;
$$;

revoke all on function public.reverse_unclaimed_sale(uuid, text) from public;
grant execute on function public.reverse_unclaimed_sale(uuid, text) to authenticated;

-- claim sessions are issued by a trusted token resolver after a valid sold card URL is opened.
create or replace function public.claim_sold_card(
  p_claim_token text,
  p_business_id uuid,
  p_destination_mode text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session private.claim_sessions%rowtype;
  v_card public.cards%rowtype;
  v_token_hash text;
begin
  if not private.has_role('owner') then
    raise exception 'An active owner account is required';
  end if;
  if p_destination_mode not in ('direct_google', 'profile') then
    raise exception 'Invalid destination mode';
  end if;
  if not exists (select 1 from public.businesses b where b.id = p_business_id and b.owner_id = auth.uid() and b.status = 'active') then
    raise exception 'Business does not belong to this owner';
  end if;

  v_token_hash := encode(extensions.digest(p_claim_token, 'sha256'), 'hex');
  select * into v_session
  from private.claim_sessions cs
  where cs.token_hash = v_token_hash
  for update;

  if not found or v_session.consumed_at is not null or v_session.expires_at <= now() then
    raise exception 'Claim session is invalid or expired';
  end if;

  select * into v_card from public.cards where id = v_session.card_id for update;
  if not found or v_card.lifecycle_state <> 'sold_unclaimed' or v_card.owner_id is not null then
    raise exception 'Card has already been claimed or is not ready';
  end if;

  update public.cards
  set lifecycle_state = 'claimed', owner_id = auth.uid(), business_id = p_business_id,
      destination_mode = p_destination_mode, claimed_at = now()
  where id = v_card.id;

  insert into public.card_claims (card_id, owner_id, business_id)
  values (v_card.id, auth.uid(), p_business_id);
  update private.claim_sessions set consumed_at = now() where id = v_session.id;

  insert into public.audit_log (actor_user_id, actor_role, action, entity_type, entity_id, new_values)
  values (auth.uid(), 'owner', 'card_claimed', 'card', v_card.id::text,
          jsonb_build_object('business_id', p_business_id, 'destination_mode', p_destination_mode));
  return v_card.id;
end;
$$;

revoke all on function public.claim_sold_card(text, uuid, text) from public;
grant execute on function public.claim_sold_card(text, uuid, text) to authenticated;

create or replace function public.configure_owned_card(
  p_card_id uuid,
  p_business_id uuid,
  p_destination_mode text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old jsonb;
begin
  if p_destination_mode not in ('direct_google', 'profile') then
    raise exception 'Invalid destination mode';
  end if;
  if not exists (select 1 from public.businesses b where b.id = p_business_id and b.owner_id = auth.uid() and b.status = 'active') then
    raise exception 'Business does not belong to this owner';
  end if;

  select jsonb_build_object('business_id', c.business_id, 'destination_mode', c.destination_mode)
  into v_old from public.cards c
  where c.id = p_card_id and c.owner_id = auth.uid() and c.lifecycle_state = 'claimed'
  for update;
  if not found then raise exception 'Card not found'; end if;

  update public.cards set business_id = p_business_id, destination_mode = p_destination_mode where id = p_card_id;
  insert into public.audit_log (actor_user_id, actor_role, action, entity_type, entity_id, old_values, new_values)
  values (auth.uid(), 'owner', 'card_configuration_changed', 'card', p_card_id::text, v_old,
          jsonb_build_object('business_id', p_business_id, 'destination_mode', p_destination_mode));
end;
$$;

revoke all on function public.configure_owned_card(uuid, uuid, text) from public;
grant execute on function public.configure_owned_card(uuid, uuid, text) to authenticated;

create or replace function public.change_business_slug(p_business_id uuid, p_new_slug text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_slug text := lower(trim(p_new_slug));
  v_old_slug text;
begin
  if v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or char_length(v_slug) not between 3 and 80 then
    raise exception 'Invalid slug';
  end if;
  if not exists (select 1 from public.businesses b where b.id = p_business_id and b.owner_id = auth.uid())
     and not private.has_role('admin') then
    raise exception 'Forbidden';
  end if;

  select bs.slug into v_old_slug from public.business_slugs bs
  where bs.business_id = p_business_id and bs.is_current for update;
  if v_old_slug = v_slug then return v_slug; end if;
  if exists (select 1 from public.business_slugs bs where bs.slug = v_slug) then
    raise exception 'Slug is unavailable';
  end if;

  update public.business_slugs set is_current = false, retired_at = now()
  where business_id = p_business_id and is_current;
  insert into public.business_slugs (slug, business_id, is_current) values (v_slug, p_business_id, true);

  insert into public.audit_log (actor_user_id, actor_role, action, entity_type, entity_id, old_values, new_values)
  values (auth.uid(), case when private.has_role('admin') then 'admin' else 'owner' end,
          'business_slug_changed', 'business', p_business_id::text,
          jsonb_build_object('slug', v_old_slug), jsonb_build_object('slug', v_slug));
  return v_slug;
end;
$$;

revoke all on function public.change_business_slug(uuid, text) from public;
grant execute on function public.change_business_slug(uuid, text) to authenticated;

-- Row Level Security
alter table public.accounts enable row level security;
alter table public.account_roles enable row level security;
alter table public.resellers enable row level security;
alter table public.reseller_members enable row level security;
alter table public.businesses enable row level security;
alter table public.business_slugs enable row level security;
alter table public.profile_links enable row level security;
alter table public.card_batches enable row level security;
alter table public.cards enable row level security;
alter table public.card_tokens enable row level security;
alter table public.stock_transfers enable row level security;
alter table public.stock_transfer_items enable row level security;
alter table public.card_sales enable row level security;
alter table public.card_claims enable row level security;
alter table public.interaction_events enable row level security;
alter table public.audit_log enable row level security;

create policy accounts_read_self_or_admin on public.accounts for select to authenticated
using (user_id = auth.uid() or private.has_role('admin'));
create policy accounts_update_self on public.accounts for update to authenticated
using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy roles_read_self_or_admin on public.account_roles for select to authenticated
using (user_id = auth.uid() or private.has_role('admin'));

create policy resellers_read_member_or_admin on public.resellers for select to authenticated
using (private.has_role('admin') or private.is_reseller_member(id));
create policy reseller_members_read_self_or_admin on public.reseller_members for select to authenticated
using (user_id = auth.uid() or private.has_role('admin'));

create policy businesses_owner_all on public.businesses for all to authenticated
using (owner_id = auth.uid() or private.has_role('admin'))
with check (owner_id = auth.uid() or private.has_role('admin'));
create policy slugs_owner_or_admin on public.business_slugs for select to authenticated
using (private.has_role('admin') or exists (
  select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()
));
create policy links_owner_all on public.profile_links for all to authenticated
using (private.has_role('admin') or exists (
  select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()
))
with check (private.has_role('admin') or exists (
  select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()
));

create policy cards_owner_or_admin_read on public.cards for select to authenticated
using (owner_id = auth.uid() or private.has_role('admin'));
create policy batches_admin_read on public.card_batches for select to authenticated
using (private.has_role('admin'));
create policy tokens_admin_read on public.card_tokens for select to authenticated
using (private.has_role('admin'));
create policy transfers_admin_read on public.stock_transfers for select to authenticated
using (private.has_role('admin'));
create policy transfer_items_admin_read on public.stock_transfer_items for select to authenticated
using (private.has_role('admin'));
create policy sales_admin_read on public.card_sales for select to authenticated
using (private.has_role('admin'));
create policy claims_owner_or_admin_read on public.card_claims for select to authenticated
using (owner_id = auth.uid() or private.has_role('admin'));
create policy events_owner_or_admin_read on public.interaction_events for select to authenticated
using (private.has_role('admin') or exists (
  select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()
));
create policy audit_admin_read on public.audit_log for select to authenticated
using (private.has_role('admin'));

-- Minimal direct grants. Sensitive state changes go through RPC or trusted server code.
revoke all on all tables in schema public from anon, authenticated;
grant select on public.accounts, public.account_roles, public.resellers, public.reseller_members,
  public.businesses, public.business_slugs, public.profile_links, public.cards,
  public.card_claims, public.interaction_events to authenticated;
grant insert, update, delete on public.businesses, public.profile_links to authenticated;
grant insert, update on public.business_slugs to authenticated;
grant update (display_name) on public.accounts to authenticated;

grant select on public.card_batches, public.card_tokens, public.stock_transfers,
  public.stock_transfer_items, public.card_sales, public.audit_log to authenticated;

-- Public profile and slug resolution must be exposed by a trusted Edge Function or a
-- carefully reviewed curated RPC. Anonymous clients receive no direct base-table access.
-- This prevents public profile reads from leaking owner_id and internal account relationships.

-- Neither anon nor authenticated receives direct insert rights for events, audit, tokens,
-- sales, claims, transfers, batches, or cards. Use trusted Edge Functions / RPCs.
